package com.logatron.processor.dlq;
import com.logatron.contracts.ingestion.*;import com.logatron.processor.parse.ProcessingException;import com.logatron.processor.protect.SensitiveDataMasker;import org.springframework.stereotype.Component;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.Instant;import java.util.*;
@Component public class DeadLetterFactory {private static final int PREVIEW=2048;private final SensitiveDataMasker masker;public DeadLetterFactory(SensitiveDataMasker masker){this.masker=masker;}public DeadLetterEvent create(String raw,RawLogEnvelope envelope,String stage,Exception failure,int retry){String safe=masker.mask(raw);if(safe==null)safe="";if(safe.length()>PREVIEW)safe=safe.substring(0,PREVIEW);UUID id=envelope!=null&&envelope.eventId()!=null?envelope.eventId():UUID.nameUUIDFromBytes((raw==null?"":raw).getBytes(StandardCharsets.UTF_8));String code=failure instanceof ProcessingException p?p.code():"UNEXPECTED_PROCESSING_FAILURE";String reason=masker.mask(failure.getMessage());if(reason==null||reason.isBlank())reason=code;return new DeadLetterEvent(1,id,stage,code,reason,Instant.now(),envelope==null||envelope.resource()==null?null:envelope.resource().projectId(),envelope==null||envelope.source()==null?null:envelope.source().logSourceId(),retry,safe,hash(raw));}private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((v==null?"":v).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}